-- ========================================================


function Gear_0_InLvl1:__init()
    self.controller = nil
    self.co_1 = nil   -- 发送携程请求


end


function Gear_0_InLvl1:__delete()
    self.co_1 = nil

    if not isNull(self.co_2) then 
        cs_coroutine.stop(self.co_2)
    end
    self.co_2 = nil
end



function Gear_0_InLvl1:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end


function Gear_0_InLvl1:Start()
    KTool.SetActive(self.controller.gameObject, true)

    self.quest = DreamSpaceLuaUtils.GetLuaScr(self.questBH.gameObject, "Game.DreamSpace.Level1.Quest.QuestLvl1" )
    assert( self.quest );
    self:RunFstGear()
end
    

function Gear_0_InLvl1:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_2 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- =========================================== Self ================================================ --


function Gear_0_InLvl1:RunFstGear()

    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_2 = cs_coroutine.start(function()
        self:RunWhenQuestInit()
    end)
end

-- 游戏的开场演绎结束后，第一条居中目标提示
---@return System.Collections.IEnumerator
function Gear_0_InLvl1:RunWhenQuestInit()
    while (isNull(self.quest.core)) or (not self.quest.core.isInit) do
        coroutine.yield(Yielders.EndOfFrame)
    end

    -- 切换 ui texts 显示:
    local newTask = self.quest.core:GetTask(0) -- Task

    cs_coroutine.yield_return(self.quest.ui_promptDialog:PlayEntry(newTask.taskDescription))
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2.5))
    cs_coroutine.yield_return(self.quest.ui_promptDialog:PlayOut())

    
    -- 显示第一条 task:
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
    cs_coroutine.yield_return(self.quest.ui_taskPanel:Activate())
    cs_coroutine.yield_return(self.quest.ui_taskPanel:ShowNewTask(newTask.taskDescription))

    cs_coroutine.yield_return(self.quest.floatingMarkerManager:EnableMarker(true))

    



end




return Gear_0_InLvl1
